'use strict';
let importJob=null,importGeneration=0;
function stopImport(){importGeneration++;importJob?.abort();importJob=null;}
function flowSteps(active){return `<ol class="import-steps" aria-label="Этапы назначения">${['Документ','Текст','Проверка','Аптечка','План'].map((s,i)=>`<li class="${i+1===active?'current':i+1<active?'complete':''}"><span>${i+1<active?'✓':i+1}</span>${s}</li>`).join('')}</ol>`}
function blankMed(){return{id:uid(),name:'',strength:'',form:'',dose:'',times:'',days:'',note:'',pack:'',checked:false,sourceText:'',warnings:[],complex:false}}
function openImport(){
  if(!owner())return;stopImport();draft=null;files=[];
  sheet('Из назначения — в план','Загрузите документ. Мы поможем разобрать его по шагам.',`${flowSteps(1)}<div class="import-patient">${portrait()}<div><span class="caption">Назначение для</span><h3>${esc(state.patient.name)}</h3><p>${esc(state.patient.short)} · ${esc(state.patient.age)} года</p></div></div><label class="scan-zone" tabindex="0" role="button" aria-label="Выбрать фото или PDF"><span class="scan-symbol">${icon('file')}${icon('search')}</span><strong>Добавьте назначение врача</strong><span>Фото, скан или PDF</span><input class="hidden" id="prescriptionFiles" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple><span class="btn btn-primary">${icon('upload')} Выбрать документ</span></label><label class="camera-choice" tabindex="0" role="button" aria-label="Сфотографировать назначение">${icon('camera')} Сфотографировать назначение<input class="hidden" id="prescriptionCamera" type="file" accept="image/*" capture="environment"></label><div class="import-privacy">${icon('shield')}<span>Распознавание на вашем устройстве.<br>Документ не отправляется на сервер.</span></div><p class="caption">Печатный текст на русском и английском. До 6 файлов по 10 МБ, суммарно до 10 страниц. Рукописный текст может не распознаться.</p><div class="demo-choice"><span class="label">Попробовать</span><h3>Нет документа под рукой?</h3><p>Распознайте учебное фото с двумя вымышленными препаратами.</p><button class="btn btn-soft btn-full" data-action="demoImport">Распознать пример ${icon('arrow')}</button></div><button class="text-link space" data-flow="paste">${icon('edit')} Вставить текст назначения</button>`);
}
async function demoImport(){
  if(!owner())return;const c=document.createElement('canvas');c.width=1500;c.height=1100;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle='#182b3a';x.font='bold 42px Arial';x.fillText('УЧЕБНОЕ НАЗНАЧЕНИЕ',90,100);x.font='28px Arial';x.fillText('Вымышленные препараты. Не является назначением врача.',90,160);
  const lines=['1. Учебный Альфа 10 мг, таблетки.','По 1 таблетке в 09:00 и 19:00, после еды, 7 дней.','','2. Учебный Бета 5 мг, капсулы.','По 1 капсуле в 14:00, во время еды, 5 дней.'];x.font='34px Arial';lines.forEach((l,i)=>x.fillText(l,90,300+i*78));
  const blob=await new Promise(r=>c.toBlob(r,'image/png'));await fileImport([new File([blob],'Учебное назначение.png',{type:'image/png'})],true);
}
async function fileImport(selected,demo=false){
  if(!owner()||!selected.length)return;
  if(selected.length>6||selected.some(f=>f.size>10*1024*1024||!['image/jpeg','image/png','image/webp','application/pdf'].includes(f.type))||selected.reduce((n,f)=>n+f.size,0)>30*1024*1024){toast('Выберите до 6 JPG, PNG, WebP или PDF: до 10 МБ на файл и до 30 МБ всего.');return}
  stopImport();const generation=importGeneration;files=selected;importJob=new AbortController();
  draft={title:demo?'Учебный курс':'Новое назначение',start:state.day,source:selected.map(f=>f.name).join(', '),demo,meds:[],pages:[],text:'',excluded:[],helper:state.members.find(m=>m.id!==actor().id&&m.view)?.id||'',access:false};
  sheet('Читаем назначение','Обычно это занимает несколько секунд. Большие сканы обрабатываются дольше.',`${flowSteps(2)}<div class="ocr-progress"><span class="scan-symbol scanning">${icon('file')}</span><h3 id="ocrStatus">Открываем документ</h3><p id="ocrDetail">${esc(selected[0].name)}</p><progress id="ocrProgress" max="1" value="0" aria-label="Ход распознавания"></progress><span id="ocrPercent" aria-live="polite">Подготовка</span></div><div class="import-privacy">${icon('shield')}<span>Обработка происходит в этой вкладке.<br>Дождитесь результата, прежде чем закрывать её.</span></div>`,`<button class="btn btn-white" data-action="import">Отменить</button>`);
  try{
    const result=await PrescriptionReader.read(selected,{signal:importJob.signal,onProgress:p=>{if(generation!==importGeneration||!$('#ocrStatus'))return;$('#ocrStatus').textContent=p.label;$('#ocrDetail').textContent=p.detail;$('#ocrProgress').value=p.progress;$('#ocrPercent').textContent=p.progress?Math.round(p.progress*100)+'%':'Подготовка'}});
    if(generation!==importGeneration)return;importJob=null;draft.pages=result.pages;draft.text=result.text;draft.ocr=true;parseDraft();reviewImport();
  }catch(e){if(generation!==importGeneration||e.name==='AbortError')return;importJob=null;sheet('Не удалось прочитать документ','Назначение пока не добавлено.',`${flowSteps(2)}<div class="hint orange">${icon('info')}<span>${esc(e.message||'Попробуйте более чёткое фото или PDF.')}</span></div><p class="caption">Можно повторить загрузку или вставить текст вручную. Курс создаётся только после вашей проверки.</p>`,`<button class="btn btn-white" data-flow="paste">Вставить текст</button><button class="btn btn-primary" data-action="import">Повторить</button>`)}
}
function parseDraft(){const parsed=PrescriptionParser.parse(draft.text);draft.meds=parsed.meds.map(m=>({...blankMed(),...m}));draft.parseWarnings=parsed.warnings;if(!draft.meds.length)draft.meds=[blankMed()];draft.excluded=[];draft.stockReview=null;draft.complete=false;draft.simple=false;draft.access=false;}
function pastePrescription(){stopImport();if(!draft)draft={title:'Новое назначение',start:state.day,source:'Текст, введённый пользователем',demo:false,meds:[],pages:[],text:'',excluded:[],helper:'',access:false};sheet('Текст назначения','Вставьте текст из документа врача.',`${flowSteps(2)}<form id="pasteForm"><label class="field"><span>Назначение целиком</span><textarea name="text" required minlength="10" maxlength="30000" rows="12" placeholder="Название, дозировка, форма. По …, в …, … дней.">${esc(draft.text)}</textarea></label><p class="caption">Текст будет разобран на поля. Пропуски нужно заполнить по оригиналу.</p></form>`,`<button class="btn btn-white" data-action="import">Назад</button><button class="btn btn-primary" form="pasteForm" type="submit">Разобрать текст ${icon('arrow')}</button>`)}
function documentPreview(){return `<details class="document space"><summary>${icon('file')} Оригинал и распознанный текст</summary><div class="source-pages">${draft.pages.map((p,i)=>`<details ${i===0?'open':''}><summary>Страница ${i+1} · ${esc(p.method)}${p.confidence!==null?` · ${Math.round(p.confidence)}% OCR`:''}</summary><img src="${p.preview}" alt="Страница ${i+1} исходного назначения"></details>`).join('')}</div><label class="field"><span>Извлечённый текст · можно исправить</span><textarea id="ocrText" rows="9" maxlength="30000">${esc(draft.text)}</textarea></label><button class="btn btn-soft btn-full" type="button" data-flow="reparse">Разобрать исправленный текст</button><p class="caption">Повторный разбор заменит поля ниже. Процент OCR относится к чтению символов, а не к правильности схемы.</p></details>`}
function reviewImport(){
  if(!draft)return;const d=draft,low=d.pages.some(p=>p.confidence!==null&&p.confidence<75);
  sheet('Проверьте назначение','Сверьте каждое поле с документом врача.',`${flowSteps(3)}<div class="recognition-result"><span class="med-icon">${icon('check')}</span><div><h3>${d.ocr?'Текст распознан':'Текст разобран'}</h3><p>${d.pages.length?`${d.pages.length} стр. · `:''}${d.meds.filter(m=>m.name).length} ${plural(d.meds.filter(m=>m.name).length,['препарат найден','препарата найдено','препаратов найдено'])}</p></div><span class="label orange">Нужна сверка</span></div>${low?'<div class="hint orange space">Качество текста невысокое. Сравните оригинал и результат; при необходимости загрузите более чёткое фото.</div>':''}${d.parseWarnings?.length?`<div class="hint orange space">${esc(d.parseWarnings.join(' '))}</div>`:''}${documentPreview()}<form id="reviewForm">${field('Название курса','title',d.title,'text','required maxlength="80"')}${field('Дата начала по назначению','start',d.start,'date','required')}<p class="caption">Для каждого препарата своя длительность. Если время не указано, согласуйте расписание; приложение его не подбирает.</p>${d.meds.map(reviewMed).join('')}<button class="text-link" type="button" data-action="addDraftMed">${icon('plus')} Добавить препарат</button>${d.excluded?.length?`<div class="hint orange space">Исключены из плана: ${d.excluded.map(esc).join(', ')}. Они не появятся в расписании.</div>`:''}<label class="check-row"><input type="checkbox" id="schemeSimple" ${d.simple?'checked':''} required>У включённых препаратов постоянная ежедневная схема, без изменения дозы и перерывов.</label><label class="check-row"><input type="checkbox" id="finalConsent" ${d.complete?'checked':''} required>Проверены все строки документа: название, форма, дозы, время и сроки. Исключения учтены отдельно.</label><div class="error" id="reviewError" role="alert"></div></form>`,`<button class="btn btn-white" data-action="import">Назад</button><button class="btn btn-primary" type="submit" form="reviewForm">Сверить аптечку ${icon('arrow')}</button>`);
}
function reviewMed(m,i){return `<section class="review-med"><div class="between"><span class="label gray">Препарат ${i+1}</span><button class="ghost" type="button" data-action="removeDraftMed" data-index="${i}" aria-label="Исключить препарат ${i+1}">${icon('trash')}</button></div>${m.sourceText?`<blockquote class="source-fragment">${esc(m.sourceText)}</blockquote>`:''}${m.complex?'<div class="hint orange">В строке сложная или неоднозначная схема. Она не поддерживается автоматическим планом. Уточните назначение у врача; эту строку можно исключить из плана.</div>':''}${m.warnings?.length?`<p class="field-warning">${m.warnings.map(esc).join(' · ')}</p>`:''}${field('Точное название','name_'+i,m.name,'text','required maxlength="100"')}<div class="field-grid">${field('Дозировка препарата','strength_'+i,m.strength,'text','required maxlength="50" placeholder="Не определена"')}<label class="field"><span>Форма</span><select name="form_${i}" required><option value="">Проверьте</option><option ${m.form==='Таблетки'?'selected':''}>Таблетки</option><option ${m.form==='Капсулы'?'selected':''}>Капсулы</option></select></label>${field('Штук за приём','dose_'+i,m.dose,'number','required min="0.25" max="100" step="0.25" placeholder="Не определено"')}${field('Длительность, дней','days_'+i,m.days,'number','required min="1" max="90" step="1" placeholder="Не определена"')}</div>${field('Время через запятую','times_'+i,m.times,'text','required placeholder="Например: 09:00, 19:00"')}${m.frequency?`<p class="caption">В тексте: ${m.frequency} приёма в день. Проверьте соответствие времени.</p>`:''}${field('Указания из документа','note_'+i,m.note,'text','maxlength="160" placeholder="Если указаны в назначении"')}<label class="check-row"><input type="checkbox" name="checked_${i}" ${m.checked?'checked':''} required>Сверено с назначением</label></section>`}
function collectDraft(){
  const f=$('#reviewForm');if(!f||!draft)return;const data=new FormData(f);draft.title=String(data.get('title')||'').trim();draft.start=String(data.get('start')||'');draft.complete=$('#finalConsent').checked;draft.simple=$('#schemeSimple').checked;
  draft.meds=draft.meds.map((m,i)=>({...m,name:String(data.get('name_'+i)||'').trim(),strength:String(data.get('strength_'+i)||'').trim(),form:String(data.get('form_'+i)||''),dose:data.get('dose_'+i)===''?'':Number(data.get('dose_'+i)),days:data.get('days_'+i)===''?'':Number(data.get('days_'+i)),times:String(data.get('times_'+i)||'').trim(),note:String(data.get('note_'+i)||'').trim(),checked:data.has('checked_'+i)}));
}
function validateDraft(){
  const d=draft;if(!d||!d.meds.length)return 'Добавьте хотя бы один препарат.';
  if(!d.title||!/^\d{4}-\d{2}-\d{2}$/.test(d.start)||Number.isNaN(dateObj(d.start).getTime())||d.start<state.day)return 'Проверьте название и дату начала: сегодня или позже.';
  const keys=new Set();for(const [i,m] of d.meds.entries()){
    if(m.complex)return `Препарат ${i+1}: сложная схема не поддерживается. Уточните её и исключите эту строку из автоматического плана.`;
    const times=m.times.split(',').map(s=>s.trim());m.unit=m.form==='Капсулы'?'капс.':'табл.';
    if(!m.name||!m.strength||!['Таблетки','Капсулы'].includes(m.form)||!m.checked||!Number.isFinite(m.dose)||m.dose<.25||m.dose>100||m.dose*4%1||!Number.isInteger(m.days)||m.days<1||m.days>90||times.length>8||times.some(t=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(t))||new Set(times).size!==times.length)return `Проверьте препарат ${i+1}: все обязательные поля, 1–90 дней и до 8 разных времён в формате 09:00.`;
    if(m.frequency&&m.frequency!==times.length)return `${m.name}: в тексте ${m.frequency} приёма в день, а времён указано ${times.length}. Исправьте время или ошибку в исходном распознанном тексте.`;
    const key=medKey(m);if(keys.has(key))return `${m.name} повторяется. Объедините время приёма в одной строке.`;keys.add(key);
    if(state.courses.some(c=>c.active&&c.meds.some(x=>medKey(x)===key&&c.start<=addDays(d.start,m.days-1)&&addDays(c.start,(x.days||c.days)-1)>=d.start)))return `${m.name} уже есть в пересекающемся курсе. Проверьте актуальное назначение, чтобы не дублировать приёмы.`;
  }
  if(!d.complete||!d.simple)return 'Подтвердите сверку всех строк и поддерживаемый тип схемы.';return '';
}
function flowError(id,msg){const e=$(id);if(e){e.textContent=msg;e.scrollIntoView({block:'nearest'})}else toast(msg)}
function submitCourse(){if(!owner())return;collectDraft();const error=validateDraft();if(error)return flowError('#reviewError',error);const signature=JSON.stringify([draft.start,draft.meds]);if(draft.reviewSignature!==signature)draft.stockReview=null;draft.reviewSignature=signature;draft.days=Math.max(...draft.meds.map(m=>m.days));reconcileStock()}
function reconcileStock(){
  if(!draft)return;if(!draft.stockReview)draft.stockReview=draft.meds.map(m=>{const s=stockFor(m);return {qty:s?.qty||0,pack:s?.pack||'',expiry:s?.expiry||'',checked:false}});
  sheet('Что уже есть дома','Сравниваем точное название, дозировку и форму.',`${flowSteps(4)}<div class="hint">${icon('box')}<span>Проверьте количество и срок годности на упаковках. До запуска плана изменения остаются черновиком.</span></div><form id="reconcileForm">${draft.meds.map((m,i)=>{const s=draft.stockReview[i],existing=stockFor(m);return `<section class="review-med"><div class="between"><h3>${esc(m.name)}</h3><span class="label ${existing?'':'gray'}">${existing?'Есть в аптечке':'Нет записи'}</span></div><p class="small muted">${esc(m.strength)} · ${esc(m.form)}</p><div class="need-summary"><span>На этот курс</span><strong>${m.dose*m.times.split(',').length*m.days} ${esc(m.unit)}</strong></div><div class="field-grid">${field('Есть дома, штук','qty_'+i,s.qty,'number','required min="0" max="100000" step="0.25"')}${field('Штук в упаковке','pack_'+i,s.pack,'number','min="1" max="1000" step="1" placeholder="Если известно"')}</div>${field('Годен до','expiry_'+i,s.expiry,'date','')}<p class="caption">Срок обязателен при наличии запаса. Если он истекает до конца курса, этот запас не учитываем. Для партий с разными сроками укажите только подходящую партию.</p><label class="check-row"><input type="checkbox" name="stockChecked_${i}" ${s.checked?'checked':''} required>Форма, дозировка, количество и срок проверены</label></section>`}).join('')}<div id="reconcileError" class="error" role="alert"></div></form>`,`<button class="btn btn-white" data-flow="backReview">Назад</button><button class="btn btn-primary" form="reconcileForm" type="submit">Список покупок ${icon('arrow')}</button>`);
}
function collectReconciliation(){const f=$('#reconcileForm');if(!f||!draft)return;const d=new FormData(f);draft.stockReview=draft.meds.map((m,i)=>({qty:d.get('qty_'+i)===''?NaN:Number(d.get('qty_'+i)),pack:d.get('pack_'+i)?Number(d.get('pack_'+i)):null,expiry:String(d.get('expiry_'+i)||''),checked:d.has('stockChecked_'+i)}))}
function validateReconciliation(){for(const [i,s] of draft.stockReview.entries())if(!s.checked||!Number.isFinite(s.qty)||s.qty<0||s.qty>100000||s.qty*4%1||(s.pack!==null&&(!Number.isInteger(s.pack)||s.pack<1||s.pack>1000))||(s.qty>0&&(!/^\d{4}-\d{2}-\d{2}$/.test(s.expiry)||Number.isNaN(dateObj(s.expiry).getTime()))))return `Проверьте остаток, упаковку и срок у препарата ${i+1}.`;return ''}
function draftNeeds(){return draft.meds.map((m,i)=>{const s=draft.stockReview[i],end=addDays(draft.start,m.days-1),usable=s.expiry&&s.expiry>=end?s.qty:0,needed=m.dose*m.times.split(',').length*m.days;let reserved=0;for(const c of state.courses.filter(c=>c.active))for(let day=0;day<c.days;day++){const date=addDays(c.start,day);if(date<state.day)continue;for(const other of c.meds)if(day<(other.days||c.days)&&medKey(other)===medKey(m))for(const t of other.times)if(!['taken','skipped'].includes(state.logs[[c.id,other.id,date,t].join('|')]?.status))reserved+=other.dose}const missing=Math.max(0,needed+reserved-usable);return {med:m,stock:s,needed,reserved,usable,missing,packs:s.pack?Math.ceil(missing/s.pack):null}})}
function importSummary(){
  const needs=draftNeeds(),missing=needs.filter(n=>n.missing>0);sheet('Всё готово к запуску','Проверьте покупки и доступ помощника.',`${flowSteps(5)}<div class="launch-summary"><span class="scan-symbol">${icon('calendar')}</span><h3>${esc(draft.title)}</h3><p>${draft.meds.length} препарата · с ${fmt(draft.start)}</p><strong>${draft.meds.reduce((sum,m)=>sum+m.times.split(',').length*m.days,0)} приёмов в расписании</strong></div><h3 class="space">${missing.length?'Нужно докупить':'Запасов хватает'}</h3><p class="caption">Только подтверждённый дефицит. Покупки не оформляются автоматически.</p>${needs.map(n=>`<div class="import-shopping"><div class="between"><strong>${esc(n.med.name)}</strong><span class="label ${n.missing?'orange':''}">${n.missing?`Не хватает ${n.missing}`:'Хватает'}</span></div><p>${esc(n.med.strength)} · ${esc(n.med.form)}</p><div class="formula">Курс ${n.needed}${n.reserved?` + другие курсы ${n.reserved}`:''} − годных дома ${n.usable} = <strong>${n.missing} ${esc(n.med.unit)}</strong></div>${n.stock.qty>n.usable?'<p class="field-warning">Запас с истекающим сроком не включён в расчёт.</p>':''}${n.missing?`<p class="small">${n.packs?`Докупить ${n.packs} уп. по ${n.stock.pack} шт.`:'Размер упаковки не указан — список в штуках.'}</p>`:''}</div>`).join('')}<form id="launchForm"><label class="field"><span>Помощник, который видит план</span><select name="helper"><option value="">Без помощника</option>${state.members.filter(m=>m.id!==actor().id&&m.view).map(m=>`<option value="${esc(m.id)}" ${draft.helper===m.id?'selected':''}>${esc(m.name)} · ${esc(m.relation)}</option>`).join('')}</select></label><label class="check-row"><input name="access" type="checkbox" required ${draft.access?'checked':''}>Есть согласие близкого или полномочия законного представителя на ведение плана и выбранный доступ.</label><div class="hint gray">${icon('bell')}<span>После запуска появятся расписание, отметки и сигналы семье. В прототипе уведомления и семейные роли работают внутри этого браузера.</span></div>${draft.excluded.length?`<p class="field-warning">Не включены: ${draft.excluded.map(esc).join(', ')}.</p>`:''}<div id="launchError" class="error" role="alert"></div></form>`,`<button class="btn btn-white" data-flow="backStock">Назад</button><button class="btn btn-primary" form="launchForm" type="submit">Запустить план ${icon('check')}</button>`);
}
function launchCourse(form){
  if(!owner()||!draft||draft.launching)return;const data=new FormData(form);if(!data.has('access'))return;const err=validateDraft()||validateReconciliation();if(err)return flowError('#launchError',err);draft.launching=true;
  const c={id:uid(),title:draft.title,start:draft.start,days:draft.days,active:true,demo:draft.demo,source:draft.source,importMethod:draft.ocr?'local-ocr':'text',verifiedBy:actor().name,helper:String(data.get('helper')||''),excluded:[...draft.excluded],meds:draft.meds.map((m,i)=>({id:m.id,name:m.name,strength:m.strength,form:m.form,unit:m.unit,dose:m.dose,days:m.days,times:m.times.split(',').map(t=>t.trim()).sort(),note:m.note,pack:draft.stockReview[i].pack,color:['','sand','lilac'][i%3]}))};
  const next=JSON.parse(JSON.stringify(state));c.meds.forEach((m,i)=>{let s=next.stock.find(s=>medKey(s)===medKey(m));const value={name:m.name,strength:m.strength,form:m.form,unit:m.unit,...draft.stockReview[i],verifiedAt:state.day};delete value.checked;if(s)Object.assign(s,value);else next.stock.push({id:uid(),...value})});next.courses.push(c);next.audit.unshift({id:uid(),type:'course',courseId:c.id,title:actor().name+' проверила назначение и запустила план',detail:c.title+' · '+c.meds.length+' препарата · аптечка сверена',date:state.day,time:hm(state.clock)});
  try{localStorage.setItem(KEY,JSON.stringify(next))}catch{draft.launching=false;return flowError('#launchError','Не удалось сохранить план. Освободите место в браузере и повторите. Назначение пока не добавлено.')}
  state=next;selectedDate=c.start;closeSheet();navigate('plan');sheet('План запущен','От назначения до ежедневной заботы.',`<div class="launch-summary"><span class="scan-symbol">${icon('check')}</span><h3>${esc(c.title)}</h3><p>Расписание и покупки сохранены.<br>Приёмы доступны для отметок и контроля.</p></div><div class="hint">${icon('users')}<span>${c.helper?`${esc(state.members.find(m=>m.id===c.helper)?.name||'Помощник')} может посмотреть план в своей демо-роли.`:'План доступен организатору ухода.'}</span></div>`,`<button class="btn btn-white" data-action="gotoShopping">Что докупить</button><button class="btn btn-primary" data-action="close">Открыть план</button>`);
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-flow]');if(!b)return;const action=b.dataset.flow;if(action==='paste')pastePrescription();if(action==='reparse'&&draft){const t=$('#ocrText').value.trim();if(!t)return toast('Добавьте текст назначения.');draft.text=t;parseDraft();reviewImport()}if(action==='backReview'){collectReconciliation();reviewImport()}if(action==='backStock'){const f=$('#launchForm');if(f){const d=new FormData(f);draft.helper=String(d.get('helper')||'');draft.access=d.has('access')}reconcileStock()}});
document.addEventListener('change',e=>{if(e.target.id==='prescriptionCamera')fileImport([...e.target.files]);if(e.target.closest('#reviewForm')&&e.target.tagName==='SELECT'){const m=e.target.closest('.review-med');if(m)$('input[type=checkbox]',m).checked=false;$('#finalConsent').checked=false}});
document.addEventListener('submit',e=>{if(e.target.id==='pasteForm'){e.preventDefault();draft.text=String(new FormData(e.target).get('text')).trim();parseDraft();reviewImport()}if(e.target.id==='reconcileForm'){e.preventDefault();collectReconciliation();const error=validateReconciliation();if(error)flowError('#reconcileError',error);else importSummary()}if(e.target.id==='launchForm'){e.preventDefault();launchCourse(e.target)}});

document.addEventListener("keydown",e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches(".scan-zone,.camera-choice")){e.preventDefault();e.target.querySelector("input").click()}});
